solution:
import SwiftUI

struct PracticeView: View {
    let items = ["A", "B", "C"]

    var body: some View {
        ScrollView {
            LazyVStack {
                ForEach(items, id: \.self) { item in
                    Text(item)
                        .swipeActions {
                            Button("Löschen", role: .destructive) { }
                        }
                }
            }
        }
        .swipeActionsContainer()
    }
}
